#!/bin/bash
# Regression cases for compare-generated.sh (review rv010, finding N1).
# Usage: compare-generated-test.sh <empty-workdir>
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"; cmp="$here/compare-generated.sh"
work="$1"; mkdir -p "$work"
failures=0

source_file() { # <version> <time> <declaration>
  printf '%s\n' '//' \
    "// This file was generated by the Eclipse Implementation of JAXB, v$1 " \
    '// See https://eclipse-ee4j.github.io/jaxb-ri ' \
    "// Generated on: $2 " '//' '' 'package org.example;' '' "$3" ''
}
episode() { # <version> <time>
  printf '%s\n' '<?xml version="1.0" encoding="UTF-8" standalone="no"?>' '<bindings version="2.1">' '    <!--' '' \
    "This file was generated by the Eclipse Implementation of JAXB, v$1 " 'See https://eclipse-ee4j.github.io/jaxb-ri ' \
    "Generated on: $2 " '' '  -->' '</bindings>'
}
tree() { # <dir> <version> <time> <declaration of A>
  mkdir -p "$1/org/example" "$1/META-INF"
  source_file "$2" "$3" "$4" > "$1/org/example/A.java"
  source_file "$2" "$3" 'public class B {}' > "$1/org/example/B.java"
  episode "$2" "$3" > "$1/META-INF/sun-jaxb.episode"
}
check() { # <case> <expected exit> <tree-b>
  bash "$cmp" "$work/base" "$3" > "$work/$1.log" 2>&1; rc=$?
  if [ "$rc" -eq "$2" ]; then echo "PASS $1 (exit $rc)"; else echo "FAIL $1: exit $rc, expected $2"; failures=$((failures+1)); fi
}

rm -rf "$work"/*
tree "$work/base" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'

tree "$work/same" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
check identical 0 "$work/same"

tree "$work/comments" 2.3.7 '2026.10.27 at 01:00:00 AM EDT' 'public class A {}'
check comment-only 0 "$work/comments"

tree "$work/added" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
cp "$work/added/org/example/B.java" "$work/added/org/example/C.java"
check added-file 1 "$work/added"

tree "$work/missing" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
rm "$work/missing/org/example/B.java"
check missing-file 1 "$work/missing"

tree "$work/declaration" 2.3.7 '2026.10.27 at 01:00:00 AM EDT' 'public class A implements java.io.Serializable {}'
check changed-declaration 1 "$work/declaration"

tree "$work/comment-text" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
sed -i '' 's#// See https://eclipse-ee4j.github.io/jaxb-ri #// See elsewhere#' "$work/comment-text/org/example/A.java"
check other-comment 1 "$work/comment-text"

tree "$work/episode-text" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
sed -i '' 's#<bindings version="2.1">#<bindings version="3.0">#' "$work/episode-text/META-INF/sun-jaxb.episode"
check episode-change 1 "$work/episode-text"

tree "$work/binary" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
printf 'header\0a\n' > "$work/base/org/example/data.bin"
printf 'header\0b\n' > "$work/binary/org/example/data.bin"
check binary-difference 1 "$work/binary"
rm "$work/base/org/example/data.bin"

tree "$work/no-newline" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
printf '%s' "$(cat "$work/no-newline/org/example/B.java")" > "$work/no-newline/org/example/B.java"
check missing-final-newline 1 "$work/no-newline"

tree "$work/unreadable" 2.3.3 '2026.10.26 at 11:00:00 PM EDT' 'public class A {}'
chmod 000 "$work/unreadable/org/example/A.java"
check unreadable-file 2 "$work/unreadable"
chmod 644 "$work/unreadable/org/example/A.java"

check absent-tree 2 "$work/does-not-exist"

echo "failures: $failures"
[ "$failures" -eq 0 ]
